-- Batch 02: reviewed internal project material pages, immutable source hashes.
BEGIN;
SET LOCAL lock_timeout='5s';
SET LOCAL statement_timeout='60s';
SET LOCAL application_name='colliers_ai_backfill_20261124_v4';
DO $fill$
DECLARE r record; n int:=0; old_count int; changed int; ev uuid; now_ts timestamptz; read_value jsonb; source_row jsonb; sub_batch int:=2; expected_before int:=24; expected_added int:=25;
BEGIN
 PERFORM pg_advisory_xact_lock(hashtext('ai_building_field_backfill_20261124_v4_100'));
 SELECT count(*) INTO old_count FROM public.audit_logs WHERE action_type='AI_FIELD_FILL' AND details->>'batch_ref'='ai_building_field_backfill_20261124_v4_100';
 IF old_count<>expected_before OR old_count+expected_added>100 THEN RAISE EXCEPTION 'batch sequence guard: %',old_count; END IF;
 -- Serialize the brief data transaction against other writes, not normal reads.
 LOCK TABLE public.buildings,public.building_brochure_data,public.building_data_field_provenance IN SHARE ROW EXCLUSIVE MODE;
 LOCK TABLE public.project_material_library,public.project_material_library_pages IN SHARE MODE;
 FOR r IN
 WITH specs AS (SELECT * FROM jsonb_to_recordset($spec$[{"lib":"7e432fcc-8bcd-5b48-88e5-eadac3750528","pg":14,"f":"power_system","type":"text","unit":"configuration","pat":"供电系统[[:space:]]+(双路供电)","hash":"a273b1db8410446fe62f5bf0debf8d1ee6f0a1d49de663de97fd1cb42bdd391a","note":"archived reviewed project parameter; historical, not independent current survey"},{"lib":"73434390-cc97-5cf8-8339-339e265cb304","pg":4,"f":"power_system","type":"text","unit":"configuration","pat":"(双路10千伏[+]紧急供电系统)","hash":"711112233d50f01d44343864f171f6cc603a1618fe74c9afef2f6bd0dbdb8166","note":"archived reviewed project parameter; historical, not independent current survey"},{"lib":"73434390-cc97-5cf8-8339-339e265cb304","pg":4,"f":"elevator_vip","type":"integer","unit":"count","pat":"([0-9]+)部VIP专用客梯","hash":"711112233d50f01d44343864f171f6cc603a1618fe74c9afef2f6bd0dbdb8166","note":"VIP dedicated passenger lift, subset of existing passenger count; do not sum again"},{"lib":"fda49630-14bd-5752-87f6-829181d0e96f","pg":11,"f":"hvac_system","type":"text","unit":"configuration","pat":"空调系统[[:space:]]+(智能VRV,24小时自由开启，可局部调节室温)","hash":"bbe050ea2183d4e6d8d1f3dabdc69fa1c984a182b9a9ff5ce73828d731122981","note":"same configuration on p11/p14"},{"lib":"fda49630-14bd-5752-87f6-829181d0e96f","pg":11,"f":"hvac_fresh_air_capacity","type":"numeric","unit":"m3/h/person","pat":"新风量[[:space:]]+([0-9]+)m3／h.p","hash":"bbe050ea2183d4e6d8d1f3dabdc69fa1c984a182b9a9ff5ce73828d731122981","note":"same value on p11 and p14"},{"lib":"fda49630-14bd-5752-87f6-829181d0e96f","pg":11,"f":"hvac_pm25_purification","type":"boolean","unit":"boolean","pat":"(PM2[.]5空气净化系统[[:space:]]+配备)","hash":"bbe050ea2183d4e6d8d1f3dabdc69fa1c984a182b9a9ff5ce73828d731122981","note":"same configuration on p11 and p14"},{"lib":"fda49630-14bd-5752-87f6-829181d0e96f","pg":11,"f":"power_system","type":"text","unit":"configuration","pat":"双路供电[[:space:]]+(市政双路供电)","hash":"bbe050ea2183d4e6d8d1f3dabdc69fa1c984a182b9a9ff5ce73828d731122981","note":"archived reviewed project parameter; historical, not independent current survey"},{"lib":"071dd93a-b56d-509c-89fe-7b01f2e822b2","pg":8,"f":"green_building_standard","type":"text","unit":"historical_certification_label","pat":"(中国绿色建筑二星)","hash":"50e50daa9176cfa2ebf6653abbe717dbe06ce8717237333ddb3c19174df3cc48","note":"historical brochure claim; not independent current certification"},{"lib":"071dd93a-b56d-509c-89fe-7b01f2e822b2","pg":8,"f":"leed_certification","type":"text","unit":"historical_certification_label","pat":"(LEED-CS[[:space:]]*金[[:space:]]*级)","hash":"50e50daa9176cfa2ebf6653abbe717dbe06ce8717237333ddb3c19174df3cc48","note":"historical brochure claim; not independent current certification"},{"lib":"c5d48ac2-02a1-509f-9c6f-8e06bc658051","pg":8,"f":"building_height","type":"numeric","unit":"m","pat":"总高度[[:space:]]+([0-9]+)m","hash":"f57b3dcbda1548608e669863a65552dc2a50c8312d7b088696341ea185afda45","note":"archived reviewed project parameter; historical, not independent current survey"},{"lib":"c5d48ac2-02a1-509f-9c6f-8e06bc658051","pg":8,"f":"facade_type","type":"text","unit":"configuration","pat":"外立面材料[[:space:]]+(石材[+]玻璃幕墙)","hash":"f57b3dcbda1548608e669863a65552dc2a50c8312d7b088696341ea185afda45","note":"archived reviewed project parameter; historical, not independent current survey"},{"lib":"c5d48ac2-02a1-509f-9c6f-8e06bc658051","pg":8,"f":"floor_load_office","type":"integer","unit":"kg/m2","pat":"楼板承重[[:space:]]+([0-9]+)KG/㎡","hash":"f57b3dcbda1548608e669863a65552dc2a50c8312d7b088696341ea185afda45","note":"archived reviewed project parameter; historical, not independent current survey"},{"lib":"c5d48ac2-02a1-509f-9c6f-8e06bc658051","pg":8,"f":"power_system","type":"text","unit":"configuration","pat":"供电系统[[:space:]]+(双路供电，10KV)","hash":"f57b3dcbda1548608e669863a65552dc2a50c8312d7b088696341ea185afda45","note":"archived reviewed project parameter; historical, not independent current survey"},{"lib":"c5d48ac2-02a1-509f-9c6f-8e06bc658051","pg":8,"f":"telecom_provider","type":"text","unit":"provider_names","pat":"网络运营商[[:space:]]+(电信、联通、移动)","hash":"f57b3dcbda1548608e669863a65552dc2a50c8312d7b088696341ea185afda45","note":"archived reviewed project parameter; historical, not independent current survey"},{"lib":"1121e64e-d60e-5334-bf63-be5f8e4abec0","pg":14,"f":"column_free","type":"boolean","unit":"boolean","pat":"(办公区域采用无柱式的空间设计)","hash":"9bd26dec5bdaf122e6d3bcf3f2137d11d1949a8f8560e7634fa33bb7b33f27f9","note":"archived reviewed project parameter; historical, not independent current survey"},{"lib":"1121e64e-d60e-5334-bf63-be5f8e4abec0","pg":14,"f":"column_spacing","type":"numeric","unit":"m","pat":"长([0-9]+)米的柱距间隔","hash":"9bd26dec5bdaf122e6d3bcf3f2137d11d1949a8f8560e7634fa33bb7b33f27f9","note":"archived reviewed project parameter; historical, not independent current survey"},{"lib":"56d040aa-8fb1-5044-b41e-baec00e52a1a","pg":10,"f":"raised_floor_cm","type":"integer","unit":"cm","pat":"办公区网络地板高度：([0-9]+)公分","hash":"03096dfe52f18974ffbc5e9e77597ff8116f8546133ae1bbb95a68deb59f82cd","note":"archived reviewed project parameter; historical, not independent current survey"},{"lib":"56d040aa-8fb1-5044-b41e-baec00e52a1a","pg":10,"f":"floor_load_office","type":"integer","unit":"kg/m2","pat":"办公([0-9]+)公斤/平米","hash":"03096dfe52f18974ffbc5e9e77597ff8116f8546133ae1bbb95a68deb59f82cd","note":"office load only"},{"lib":"56d040aa-8fb1-5044-b41e-baec00e52a1a","pg":12,"f":"hvac_cooling_water_24h","type":"boolean","unit":"boolean","pat":"(24小时冷却水)","hash":"e9cc5d47f00312acfb2650f163082e3a3e413134c702e4fbad0396ee6cca2953","note":"archived reviewed project parameter; historical, not independent current survey"},{"lib":"44c92741-e2bb-53f3-83c7-793c8705bac8","pg":17,"f":"column_spacing","type":"numeric","unit":"m","pat":"柱距([0-9]+)米","hash":"7b334a2261c46aa687e6dcefe5279ec64ecbf08d1983a52b32ffa1d39f2a2dc0","note":"archived reviewed project parameter; historical, not independent current survey"},{"lib":"44c92741-e2bb-53f3-83c7-793c8705bac8","pg":17,"f":"depth","type":"numeric","unit":"m","pat":"进深([0-9]+)米","hash":"7b334a2261c46aa687e6dcefe5279ec64ecbf08d1983a52b32ffa1d39f2a2dc0","note":"archived reviewed project parameter; historical, not independent current survey"},{"lib":"44c92741-e2bb-53f3-83c7-793c8705bac8","pg":17,"f":"column_free","type":"boolean","unit":"boolean","pat":"(无柱式空间结构)","hash":"7b334a2261c46aa687e6dcefe5279ec64ecbf08d1983a52b32ffa1d39f2a2dc0","note":"archived reviewed project parameter; historical, not independent current survey"},{"lib":"44c92741-e2bb-53f3-83c7-793c8705bac8","pg":24,"f":"power_system","type":"text","unit":"configuration","pat":"(真双路供电)","hash":"034559e93d483e903c70ebe203632d6054047892aaff58a4da428398da24d2ba","note":"archived reviewed project parameter; historical, not independent current survey"},{"lib":"851b569c-92a5-5daf-9b33-b2ac0d95b678","pg":5,"f":"power_system","type":"text","unit":"configuration","pat":"写字楼供电量[[:space:]]+(双路供电，89千伏安/层)","hash":"cff5629d024085ced9640b51635d499ec31000fb133456c180ec641e2a02c395","note":"archived reviewed project parameter; historical, not independent current survey"},{"lib":"58839839-303e-5716-aff6-f0ef8dc7c30d","pg":11,"f":"hvac_fresh_air_capacity","type":"numeric","unit":"m3/h/person","pat":"新风量[[:space:]]+([0-9]+)m³/h[.]per person","hash":"f3e7cf6ffb98bda7e3e2927697bcea16cc585282293624fe7f5161a4d82710ba","note":"archived reviewed project parameter; historical, not independent current survey"}]$spec$::jsonb) v(lib uuid,pg int,f text,type text,unit text,pat text,hash text,note text)), scope AS (
SELECT l.id lib,(array_agg(distinct bid::uuid))[1] bid FROM public.project_material_library l CROSS JOIN LATERAL jsonb_array_elements(l.payload->'sections') s CROSS JOIN LATERAL jsonb_array_elements_text(CASE WHEN jsonb_typeof(s->'candidate_building_ids')='array' THEN s->'candidate_building_ids' ELSE '[]'::jsonb END) bid WHERE l.review_state='reviewed' AND s->>'association_status'='confirmed' GROUP BY l.id HAVING count(distinct bid)=1
), c AS (
SELECT b.id bid,b.name,d.id target_id,v.f field_name,
 CASE v.type WHEN 'numeric' THEN to_jsonb(m.val::numeric) WHEN 'integer' THEN to_jsonb(m.val::integer) WHEN 'boolean' THEN to_jsonb(true) ELSE to_jsonb(trim(regexp_replace(m.val,'[[:space:]]+',' ','g'))) END new_value,
 v.type value_type,'project_material_library' source_table,l.id source_id,'page:'||v.pg source_field,'internal_archived_page' source_kind,v.unit,
 v.note||'; page_sha256='||v.hash||'; original native text preserved inside database' note
FROM specs v JOIN scope s ON s.lib=v.lib JOIN public.project_material_library l ON l.id=s.lib
JOIN public.project_material_library_pages p ON p.extraction_id=l.id AND p.page_number=v.pg AND p.content_sha256=v.hash
JOIN public.buildings b ON b.id=s.bid JOIN public.building_brochure_data d ON d.building_id=b.id
CROSS JOIN LATERAL (SELECT (regexp_match(p.content->>'native_text',v.pat))[1] val) m
WHERE b.is_active AND b.city IN ('北京','北京市') AND b.project_type='stock' AND b.tracking_scope='tracked' AND b.merged_into_id IS NULL AND (SELECT count(*) FROM public.building_brochure_data d2 WHERE d2.building_id=b.id)=1
AND to_jsonb(d)->v.f='null'::jsonb AND m.val IS NOT NULL
) SELECT c.* FROM c
WHERE NOT EXISTS (SELECT 1 FROM public.building_data_field_provenance p WHERE p.building_id=c.bid AND p.target_table='building_brochure_data' AND p.field_name=c.field_name)
AND NOT EXISTS (SELECT 1 FROM public.audit_logs a WHERE a.action_type='AI_FIELD_FILL' AND a.target_table='building_brochure_data' AND a.target_id=c.target_id::text AND (a.details->>'field_name'=c.field_name OR a.new_values ? c.field_name))
ORDER BY target_id,field_name
 LOOP
  IF r.new_value IS NULL OR r.new_value='null'::jsonb OR r.value_type NOT IN ('text','integer','numeric','boolean','date') THEN RAISE EXCEPTION 'invalid candidate'; END IF;
  ev:=gen_random_uuid(); now_ts:=clock_timestamp();
  EXECUTE format('UPDATE public.building_brochure_data SET %I=($2#>>''{}'')::%s WHERE id=$1 AND building_id=$3 AND %I IS NULL',r.field_name,r.value_type,r.field_name) USING r.target_id,r.new_value,r.bid;
  GET DIAGNOSTICS changed=ROW_COUNT;
  IF changed<>1 THEN RAISE EXCEPTION 'null protection failed'; END IF;
  INSERT INTO public.building_data_field_provenance(building_id,brochure_data_id,target_table,field_name,field_value,source_type,source_tier,source_name,source_retrieved_at,value_recorded_at,verification_status,evidence_group_id,evidence_note,is_current)
  VALUES(r.bid,r.target_id,'building_brochure_data',r.field_name,r.new_value,'brochure','secondary','高力国际已审阅历史项目资料',now_ts,now_ts,'legacy_backfill',ev,'batch_ref=ai_building_field_backfill_20261124_v4_100; source_table='||r.source_table||'; source_record_id='||r.source_id||'; source_field='||r.source_field||'; unit='||r.unit||'; '||r.note||'; AI-assisted',true);
  INSERT INTO public.audit_logs(id,user_id,action_type,details,request_source,module,target_table,target_id,target_name,old_values,new_values,event_id,occurred_at,actor_kind,actor_name)
  VALUES(nextval('public.audit_logs_id_seq'),'codex','AI_FIELD_FILL',jsonb_build_object('batch_ref','ai_building_field_backfill_20261124_v4_100','sub_batch',sub_batch,'building_id',r.bid,'field_name',r.field_name,'source_table',r.source_table,'source_record_id',r.source_id,'source_field',r.source_field,'source_kind',r.source_kind,'unit',r.unit,'verification_status','legacy_backfill','evidence_group_id',ev,'ai_assisted',true,'reversible',true),'codex_mcp','building_brochure_data','building_brochure_data',r.target_id::text,r.name,jsonb_build_object(r.field_name,NULL),jsonb_build_object(r.field_name,r.new_value),'ai_field_fill:'||ev::text,now_ts,'tool','Codex（工具执行）');
  EXECUTE format('SELECT to_jsonb(%I) FROM public.building_brochure_data WHERE id=$1',r.field_name) INTO read_value USING r.target_id;
  IF read_value IS DISTINCT FROM r.new_value OR NOT EXISTS(SELECT 1 FROM public.building_data_field_provenance p JOIN public.audit_logs a ON a.event_id='ai_field_fill:'||ev::text WHERE p.evidence_group_id=ev AND p.is_current AND p.field_value=read_value AND a.new_values->r.field_name=p.field_value AND a.old_values->r.field_name='null'::jsonb) THEN RAISE EXCEPTION 'readback failed'; END IF;
  n:=n+1;
 END LOOP;
 IF n<>expected_added THEN RAISE EXCEPTION 'expected % qualifying fields, got %',expected_added,n; END IF;
END $fill$;
SELECT count(*) cumulative,count(distinct (target_table,target_id,details->>'field_name')) unique_fields FROM public.audit_logs WHERE action_type='AI_FIELD_FILL' AND details->>'batch_ref'='ai_building_field_backfill_20261124_v4_100';
COMMIT;